func loadCheckpoints(dir string) ([]*types.CheckpointFile, error) {
        ap, err := DiscoverArtifacts(dir)
        if err != nil {
                return nil, err
        }
        var cps []*types.CheckpointFile
        for _, p := range ap.Checkpoints {
                cf, err := checkpoint.Parse(p)
                if err != nil || cf == nil {
                        continue
                }
                cps = append(cps, cf)
        }
        sort.Slice(cps, func(i, j int) bool {
                return cps[i].Filename < cps[j].Filename
        })
        return cps, nil
}

type DetectOutput struct {
        Status    string          `json:"status"`
        Anomalies []types.Anomaly `json:"anomalies"`
        Summary   struct {
                Total      int            `json:"total"`
                BySeverity map[string]int `json:"by_severity"`
                ByType     map[string]int `json:"by_type"`
        } `json:"summary"`
}

func BuildDetect(dir string) (interface{}, error) {
        return buildDetectWithDir(dir)
}

func buildDetectWithDir(dir string) (DetectOutput, error) {
        var out DetectOutput
        out.Status = "ok"
        var anomalies []types.Anomaly

        entries, _, err := loadTimelineEntries(dir)
        if err == nil {
                merged, _ := mergeTimeline(entries)
                sortTimeline(merged)
                anomalies = append(anomalies, detectTimelineAnomalies(merged)...)
        }

        cps, err := loadCheckpoints(dir)
        if err == nil {
                anomalies = append(anomalies, detectCheckpointAnomalies(dir, cps)...)
        }

        for i := range anomalies {
                anomalies[i].ID = fmt.Sprintf("ANOM-%03d", i+1)
        }
        sortAnomalies(anomalies)

        out.Anomalies = anomalies
        if out.Anomalies == nil {
                out.Anomalies = []types.Anomaly{}
        }
        out.Summary.Total = len(anomalies)
        out.Summary.BySeverity = map[string]int{"critical": 0, "high": 0, "medium": 0, "low": 0}
        out.Summary.ByType = map[string]int{}
        for _, a := range anomalies {
                out.Summary.BySeverity[a.Severity]++
                out.Summary.ByType[a.Type]++
        }
        return out, nil
}

func detectTimelineAnomalies(entries []types.TimelineEntry) []types.Anomaly {
        var anomalies []types.Anomaly
        anomalies = append(anomalies, detectGradientSpikes(entries)...)
        anomalies = append(anomalies, detectLossDivergence(entries)...)
        anomalies = append(anomalies, detectLrAnomalies(entries)...)
        anomalies = append(anomalies, detectTrainingGaps(entries)...)
        anomalies = append(anomalies, detectMetricRegression(entries)...)
        return anomalies
}

