func BuildDetect(dir string) (interface{}, error) {
        return BuildDetectFiltered(dir, "")
}

func BuildDetectFiltered(dir, filterSeverity string) (DetectOutput, error) {
        var out DetectOutput
        out.Status = "ok"
        var anomalies []types.Anomaly

        entries, _, err := loadTimelineEntries(dir)
        if err == nil {
                merged, _ := mergeTimeline(entry)
                sortTimeline(merged)
                anomalies = append(anomalies, detectTimelineAnomalies(merged)...)
        }

        cps, err := loadCheckpoints(dir)
        if err == nil {
                anomalies = append(anomalies, detectCheckpointAnomalies(dir, cps)...)
        }

        if filterSeverity != "" {
                wantedRank, ok := severityRankValue(filterSeverity)
                if !ok {
                        return out, fmt.Errorf("invalid severity level %q: must be critical, high, medium, or low", filterSeverity)
                }
                filtered := anomalies[:0]
                for _, a := range anomalies {
                        if severityRank(a.Severity) <= wantedRank {
                                filtered = append(filtered, a)
                        }
                }
                anomalies = filtered
        }

        for i := range anomalies {
                anomalies[i].ID = fmt.Sprintf("ANOM-%03d", i+1)
        }
        sortAnomalies(anomalies)

        out.Anomalies = anomalies
        if out.Anomalies == nil {
                out.Anomalies = []types.Anomaly{}
        }
        out.Summary.Total = len(anomalies)
        out.Summary.BySeverity = map[string]int{"critical": 0, "high": 0, "medium": 0, "low": 0}
        out.Summary.ByType = map[string]int{}
        for _, a := range anomalies {
                out.Summary.BySeverity[a.Severity]++
                out.Summary.ByType[a.Type]++
        }
        return out, nil
}

func severityRank(s string) int { ... }

func severityRankValue(s string) (int, bool) {
        switch s {
        case "critical":
                return 0, true
        case "high":
                return 1, true
        case "medium":
                return 2, true
        case "low":
                return 3, true
        default:
                return 4, false
        }
}
```
